        controller.abort();
        stop();
      }
    } catch {
      // Best-effort polling only; transient read failures must not become unhandled rejections.
    } finally {
      polling = false;
    }
  };

  timer = setInterval(() => {
    void poll();
  }, 250);
  void poll();

  return { signal: controller.signal, stop };
}

